'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles=['Bienvenue','Moi réel','Moi présenté','Moi idéal','Mes passerelles','Mon bilan'];
let step=0,data={date:new Date().toISOString(),answers:{},scores:{},priorities:[],email:'',phone:'',remember:false};
try{const s=localStorage.getItem('ombaliz-image-v1');if(s){const p=JSON.parse(s);if(p&&p.answers&&p.scores&&Array.isArray(p.priorities))data=p}}catch{}
const dateLabel=()=>new Date(data.date).toLocaleString('fr-FR',{dateStyle:'long',timeStyle:'short'});
const groups=[
{title:'Le moi réel',sub:'Me regarder avec nuance',color:'#dcece6',intro:'C’est la façon dont je me perçois aujourd’hui, avec mes forces, mes besoins et mes fragilités. Cette image est subjective et peut évoluer : une pensée sur moi n’est pas une vérité définitive.',tip:'Je remplace une étiquette globale par un fait précis. « Je suis incapable » peut devenir « Cette tâche a été difficile aujourd’hui ; j’ai pourtant demandé de l’aide. »',q:[['real_alone','Qui suis-je lorsque je n’ai rien à prouver ?','Décrivez un moment où vous vous êtes senti(e) simplement vous-même.'],['real_strength','Quelles forces puis-je reconnaître en moi ?','Citez deux qualités et un exemple concret pour chacune.'],['real_fragile','Qu’est-ce que j’ai du mal à accepter chez moi ?','Comment cela influence-t-il mon quotidien ? Que dirais-je à un ami dans la même situation ?'],['real_label','Quelles étiquettes est-ce que je me colle ?','Par exemple : « trop sensible ». Quels faits nuancent cette étiquette ?'],['real_need','De quoi ai-je besoin pour me sentir davantage en accord avec moi ?','Du repos, de la sécurité, des liens, des limites…']],s:[['accept','Aujourd’hui, à quel point puis-je m’accueillir tel(le) que je suis ?','Très difficilement','Avec bienveillance'],['critique','À quelle fréquence ma voix intérieure est-elle dure avec moi ?','Jamais','Très souvent']]},
{title:'Le moi présenté',sub:'Comprendre mes protections',color:'#f0e1df',intro:'Le moi présenté est l’image que je montre aux autres. Adapter mon comportement à une situation est courant. Je peux explorer quand cette adaptation m’aide et quand elle m’éloigne de mes besoins.',tip:'Mon masque a peut-être essayé de me protéger. Je peux remercier cette protection et chercher une manière plus souple de me sentir en sécurité, sans tout dévoiler.',q:[['show_role','Quels rôles est-ce que je prends devant les autres ?','La personne toujours forte, drôle, disponible, parfaite… Avec qui ?'],['show_expect','Comment aimerais-je être vu(e) ?','Qu’aimerais-je que les autres disent de moi ? Que fais-je pour obtenir cette image ?'],['show_hide','Qu’est-ce que j’évite de montrer ?','Une émotion, un besoin, une difficulté… Vous pouvez rester général(e).'],['show_protect','Que cherche à protéger cette image ?','De quel jugement ou de quelle conséquence ai-je peur ? Qu’est-ce qui est certain et qu’est-ce que j’imagine ?'],['show_cost','Qu’est-ce que ce rôle m’apporte et qu’est-ce qu’il me coûte ?','Pensez à votre énergie, votre liberté, vos relations.'],['show_safe','Avec quelle personne et dans quelle situation pourrais-je être un peu plus moi-même ?','Choisissez un contexte suffisamment sûr ; il n’est pas nécessaire de tout dire.']],s:[['authentic','À quel point ce que je montre ressemble-t-il à ce que je ressens ?','Très peu','Tout à fait'],['effort','Combien d’effort me demande le maintien de cette image ?','Aucun effort','Beaucoup d’effort']]},
{title:'Le moi idéal',sub:'Choisir ma direction',color:'#f3e8c9',intro:'C’est la personne que j’aimerais devenir. Un idéal peut donner une direction ; s’il devient une obligation de perfection, il peut aussi peser. Une valeur se pratique aujourd’hui, même imparfaitement : « être attentif » plutôt que « être aimé de tous ».',tip:'Je me demande : « Si personne ne me félicitait, est-ce que cette direction compterait encore pour moi ? » Je peux garder ce qui a du sens et assouplir les exigences.',q:[['ideal_self','Comment aimerais-je être, dans une version réaliste et vivante de moi-même ?','Décrivez des attitudes plutôt qu’une image parfaite ou une apparence.'],['ideal_model','Qui m’inspire et quelle qualité précise m’inspire chez cette personne ?','Comment cette qualité pourrait-elle s’exprimer à ma façon ?'],['ideal_values','Quelles valeurs se trouvent derrière cet idéal ?','Par exemple : authenticité, curiosité, solidarité, créativité, courage.'],['ideal_pressure','Qu’est-ce qui vient de moi, et qu’est-ce qui vient des attentes des autres ?','Repérez un « je dois » et reformulez-le en un choix, si cela vous convient.'],['ideal_obstacle','Qu’est-ce qui rend cette direction difficile aujourd’hui ?','Contraintes réelles, peur, fatigue… Quel soutien me serait utile ?'],['ideal_enough','À quoi ressemblerait une version « suffisamment bonne » de cet idéal ?','Quel signe concret et modeste me ferait dire : j’avance ?']],s:[['meaning','À quel point cette direction a-t-elle du sens pour moi ?','Très peu','Énormément'],['pressure','Quelle pression est-ce que je ressens pour atteindre cet idéal ?','Aucune','Très forte']]}
];
const bridgeQ=[['bridge_scene','Un moment où j’aurais aimé être davantage moi-même','Dans une situation concrète, qu’est-ce que je ressentais ? Qu’ai-je montré aux autres ? Qu’aurais-je aimé pouvoir dire ou faire ?'],['bridge_compassion','La phrase bienveillante que je choisis de m’adresser','« C’est difficile pour moi ; je peux avancer sans être parfait(e). »'],['bridge_action','Mon petit pas, dans les sept prochains jours','Une action observable : exprimer une préférence à une personne sûre, réserver dix minutes pour moi…'],['bridge_when','Quand, où et avec quel soutien ?','Précisez un moment, un lieu et une ressource.'],['bridge_plan','Si un obstacle apparaît, quelle version plus facile pourrais-je essayer ?','Réduire la durée, préparer une phrase, demander un soutien…'],['bridge_session','Ce que j’aimerais explorer avec mon thérapeute','Une question, un besoin ou une situation à approfondir.']];
const bridgeS=[['alignment','Aujourd’hui, à quel point me semble-t-il possible de montrer aux autres qui je suis vraiment et d’avancer vers la personne que je souhaite devenir ?','Pas encore possible','Tout à fait possible'],['feasible','À quel point mon petit pas me paraît-il faisable ?','Pas encore faisable','Tout à fait faisable'],['emotion','Quel est mon niveau de tension maintenant ?','Apaisé(e)','Très tendu(e)']];

const johariSource='https://ombuds.columbia.edu/sites/default/files/content/pics/30%20Anniv/The%20Johari%20window_A%20graphic%20model%20of%20awareness%20in%20interpersonal%20relations.pdf';
const johariAreas=[['Zone ouverte','Ce que je connais de moi et que les autres connaissent aussi.'],['Zone cachée','Ce que je connais de moi et que je garde pour moi.'],['Zone aveugle','Ce que les autres perçoivent de moi et dont je n’ai pas conscience.'],['Zone inconnue','Ce que ni moi ni les autres ne connaissons encore de moi.']];
const johariLinks=[
'Le moi réel : je connais déjà certains aspects de moi. Un retour concret, proposé par une personne de confiance, peut éclairer une zone aveugle. Son regard reste un point de vue, pas un verdict.',
'Le moi présenté : je partage certaines choses (zone ouverte) et j’en garde d’autres pour moi (zone cachée). Préserver mon intimité est un choix légitime ; je n’ai pas à tout révéler.',
'Le moi idéal : il exprime une direction souhaitée, pas une case de Johari. Une expérience nouvelle et choisie peut m’aider à découvrir une ressource encore inconnue.'
];
function johariComic(){return `<section class="card comic-intro" aria-labelledby="comic-title"><div class="eyebrow">COMPRENDRE EN 4 SCÈNES</div><h3 id="comic-title">Une fenêtre pour mieux me connaître</h3><p class="small">Quatre moments du quotidien pour découvrir les zones de Johari.</p><a href="assets/johari-comic.png" target="_blank" rel="noopener" aria-label="Ouvrir la bande dessinée sur la fenêtre de Johari en grand"><img class="johari-comic" src="assets/johari-comic.png" alt="Bande dessinée en quatre scènes : zone ouverte, mon goût pour les plantes est connu de moi et de mon ami ; zone cachée, je garde mon goût du dessin pour moi ; zone aveugle, un ami remarque une patience dont je ne suis pas conscient ; zone inconnue, un nouvel atelier pourrait révéler une facette encore inconnue de tous."></a><p class="small">Touchez l’image pour l’ouvrir en grand et zoomer.</p><details><summary>Lire la bande dessinée en texte</summary><p><b>1. Zone ouverte.</b> Je le sais, les autres aussi. Un ami remarque que j’aime prendre soin des plantes ; je le sais déjà.</p><p><b>2. Zone cachée.</b> Je le sais, les autres ne le savent pas. J’aime dessiner et je choisis à qui en parler.</p><p><b>3. Zone aveugle.</b> Les autres le voient, moi pas encore. Un ami souligne ma patience en l’écoutant ; je ne m’en rendais pas compte.</p><p><b>4. Zone inconnue.</b> Ni moi ni les autres ne le savons encore. Une nouvelle expérience pourrait nous faire découvrir une ressource que nous ne connaissons pas encore.</p><p>Je peux mieux me connaître, à mon rythme, sans tout dévoiler.</p></details></section>`}
function johariCard(){return `<section class="card johari"><div class="eyebrow">UN ÉCLAIRAGE COMPLÉMENTAIRE</div><h3>La fenêtre de Johari, simplement</h3><p class="small">Luft et Ingham (1955) proposent quatre zones pour réfléchir à ce que je connais de moi et à ce que les autres en perçoivent.</p><div class="table-scroll"><table><caption>Quatre zones pour mieux me comprendre</caption><tbody>${johariAreas.map(a=>`<tr><th scope="row">${a[0]}</th><td>${a[1]}</td></tr>`).join('')}</tbody></table></div><p class="small">Ces zones varient selon la relation et le contexte. Elles complètent les trois regards de ce carnet, sans leur correspondre terme à terme. Le moi idéal n’est pas une zone de Johari.</p><p class="small">Je peux choisir ce que je partage et demander un retour bienveillant, à mon rythme.</p><a class="small" href="${johariSource}" target="_blank" rel="noopener">Référence : Joseph Luft, présentation du modèle de Johari (en anglais)</a></section>`}
groups[0].q.push(['real_feedback','Quel retour concret d’une personne de confiance m’a aidé(e) à mieux me connaître ?','Fenêtre de Johari · zone aveugle : quel exemple me donne-t-elle ? Qu’est-ce qui me parle ou mérite d’être nuancé ?']);
groups[1].q.push(['show_privacy','Qu’est-ce que je souhaite partager et qu’est-ce que je préfère garder privé ?','Fenêtre de Johari · zones ouverte et cachée : avec qui me sentirais-je suffisamment en confiance ? Je peux aussi choisir de ne rien partager.']);

const symbols=i=>`<svg viewBox="0 0 160 160" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${['Un miroir pour me regarder avec douceur','Un masque pour comprendre mes protections','Une boussole pour choisir ma direction'][i]}"><circle cx="80" cy="80" r="72" fill="${groups[i].color}"/>${[
'<path d="M66 123h28l7 16H59z" fill="#be9e72"/><rect x="75" y="105" width="10" height="24" rx="5" fill="#be9e72"/><ellipse cx="80" cy="67" rx="41" ry="51" fill="#c09f74"/><ellipse cx="80" cy="66" rx="34" ry="43" fill="#f6fbf8"/><path d="M55 93q25-22 50 0v11H55" fill="#5c8c88"/><circle cx="80" cy="59" r="17" fill="#e3bca5"/><path d="M63 55q0-23 17-19q18 0 17 22l-8-10-25 9" fill="#244d55"/><path d="M75 67q5 4 10 0" stroke="#844054" fill="none" stroke-width="2"/><path d="M51 42l13-11M53 52l19-19" stroke="#c7dedb" stroke-width="4"/>',
'<path d="M44 50Q80 25 116 50L110 99Q80 137 50 99Z" fill="#b36f7d"/><path d="M44 50Q80 66 116 50" stroke="#843952" fill="none" stroke-width="3"/><path d="M56 73q9-11 18 0q-9 10-18 0M86 73q9-11 18 0q-9 10-18 0" fill="#f9f5ef"/><path d="M66 98q14 11 28 0" stroke="#fff" stroke-width="4" fill="none" stroke-linecap="round"/><path d="M110 100l17 39" stroke="#c49b77" stroke-width="7" stroke-linecap="round"/><path d="M42 58L25 48M118 58l17-10" stroke="#843952" stroke-width="3"/>',
'<circle cx="80" cy="81" r="48" fill="#c09f70"/><circle cx="80" cy="81" r="40" fill="#fffaf0"/><path d="M80 42v10M80 110v10M41 81h10M109 81h10" stroke="#c09f70" stroke-width="3"/><path d="M99 53L86 87 61 109 74 75Z" fill="#843952"/><path d="M99 53L86 87 61 109 80 81Z" fill="#568c88"/><circle cx="80" cy="81" r="5" fill="#fffaf0"/><text x="80" y="35" text-anchor="middle" font-family="serif" font-size="14" fill="#715b32">N</text><path d="M73 18q7-9 14 0" stroke="#c09f70" fill="none" stroke-width="3"/>'
][i]}</svg>`;
function save(){if(data.remember){try{localStorage.setItem('ombaliz-image-v1',JSON.stringify(data))}catch{toast('La sauvegarde locale est indisponible. Gardez cet onglet ouvert.')}}}
function question(q,priority=true){const [id,label,hint]=q;return `<div class="question">${priority?`<button type="button" class="priority ${data.priorities.includes(id)?'chosen':''}" data-priority="${id}" aria-pressed="${data.priorities.includes(id)}">${data.priorities.includes(id)?'★ Priorité':'☆ Prioriser'}</button>`:''}<label for="${id}">${label}</label><span class="example">${hint}</span><textarea id="${id}" data-answer="${id}" placeholder="Quelques mots suffisent…">${esc(data.answers[id])}</textarea></div>`}
function scale(s){const [id,label,lo,hi]=s;return `<div class="question"><label id="label-${id}">${label}</label><div class="scale" role="group" aria-labelledby="label-${id}">${Array.from({length:11},(_,i)=>`<button type="button" data-score="${id}" data-value="${i}" aria-pressed="${data.scores[id]===i}" class="${data.scores[id]===i?'selected':''}">${i}</button>`).join('')}</div><div class="anchors"><span>0 · ${lo}</span><span>10 · ${hi}</span></div><div class="answered" id="out-${id}">${data.scores[id]===undefined?'Non renseigné':data.scores[id]+' / 10'} <button class="textbtn" data-clear="${id}">Effacer</button></div></div>`}
function welcome(){return `<div class="eyebrow">L’IMAGE DE SOI · UN PARCOURS EN 3 REGARDS</div><h2>Un peu moins de jugement.<br>Un peu plus de moi.</h2><p class="lead">Prendre le temps de comprendre l’image que j’ai de moi, les protections que je montre et la personne que je souhaite devenir.</p>${johariComic()}<div class="hero">${groups.map((g,i)=>`<div class="symbol-card">${symbols(i)}<b>${g.title}</b><span>${['Ce que je perçois de moi','Ce que je montre aux autres','Ce vers quoi je veux aller'][i]}</span></div>`).join('')}</div>${johariCard()}<div class="card"><h3>Mon point de départ</h3><p class="small">Ces coordonnées figureront dans votre bilan. Elles ne sont pas envoyées automatiquement.</p><div class="fields"><label for="email">Mon adresse email<input id="email" type="email" autocomplete="email" value="${esc(data.email)}" required placeholder="prenom@exemple.fr"></label><label for="phone">Mon numéro de téléphone<input id="phone" type="tel" autocomplete="tel" value="${esc(data.phone)}" required placeholder="06 12 34 56 78"></label></div><p class="small">Date de réponse : <strong>${dateLabel()}</strong></p><label class="check"><input id="remember" type="checkbox" ${data.remember?'checked':''}>Conserver mes réponses sur cet appareil pour reprendre plus tard. À utiliser seulement sur un appareil personnel.</label><p class="small">Sans cette option, vos réponses restent dans cet onglet et sont perdues à sa fermeture ou à son rechargement.</p><div id="validation"></div></div><div class="note"><b>Je garde la main.</b> Les questions sont facultatives. Je peux faire une pause et en parler en séance si une émotion devient trop intense. Il n’y a pas de bonne ou de mauvaise réponse.</div><p class="small">Un outil d’exploration inspiré du document de Michel Laks. Ces trois facettes de l’image de soi se distinguent des états Parent, Adulte et Enfant de l’analyse transactionnelle. Les échelles proposées ici ne sont pas des tests psychométriques validés.</p>`}
function bridge(){return `<div class="eyebrow">RAPPROCHER MES TROIS REGARDS</div><h2>Construire mes passerelles.</h2><p class="lead">L’objectif n’est pas de devenir parfait(e), mais de choisir un geste qui me ressemble, dans un contexte suffisamment sûr.</p><div class="note"><b>Une pause de douceur.</b> Je sens mes pieds au sol. Je nomme ce qui est difficile, sans me juger. Puis je cherche le soutien ou le petit geste dont j’ai besoin maintenant.</div>${scale(bridgeS[0])}${bridgeQ.map(q=>question(q)).join('')}${scale(bridgeS[1])}<p class="small">Si ce pas paraît peu faisable, je peux le réduire ou demander un soutien.</p>${scale(bridgeS[2])}<div class="note">Je peux marquer jusqu’à <b>3 priorités ★</b> parmi les questions du parcours : elles seront regroupées au début de mon bilan.</div>`}
function allQ(){return [...groups.flatMap(g=>g.q),...bridgeQ]}
function allS(){return [...groups.flatMap(g=>g.s),...bridgeS]}
function report(){const n=allQ().filter(q=>(data.answers[q[0]]||'').trim()).length;return `<div class="eyebrow">MON CARNET DE SÉANCE</div><h2>Ce que je retiens de moi.</h2><p class="lead">Une photographie de mon vécu aujourd’hui, à explorer ensemble. Aucun score global, aucune catégorie de personnalité.</p><div class="badges"><span class="badge">${n} réflexions renseignées</span><span class="badge">${Object.keys(data.scores).length} ressentis renseignés</span><span class="badge">${data.priorities.length}/3 priorités</span></div><div class="card"><h3>Mes priorités ★</h3>${data.priorities.length?data.priorities.map(id=>{const q=allQ().find(q=>q[0]===id);return `<div class="reportitem"><b>${esc(q[1])}</b><p>${esc(data.answers[id]||'À explorer en séance.')}</p></div>`}).join(''):'<p>Aucune priorité choisie. Revenez sur une question et touchez « ☆ Prioriser » si vous le souhaitez.</p>'}</div><div class="card"><h3>Mon ressenti aujourd’hui</h3>${allS().map(s=>`<div class="reportitem"><label>${s[1]}</label><span class="small">${data.scores[s[0]]===undefined?'Non renseigné':data.scores[s[0]]+' / 10'} · ${s[2]} → ${s[3]}</span>${data.scores[s[0]]!==undefined?`<div class="scorebar"><span style="width:${data.scores[s[0]]*10}%"></span></div>`:''}</div>`).join('')}</div><div class="note"><b>Mon petit pas :</b><br>${esc(data.answers.bridge_action||'Je pourrai le définir en séance.')}<br><span class="small">${esc(data.answers.bridge_when||'')}</span></div><details><summary>Relire toutes mes réflexions</summary>${allQ().map(q=>`<div class="reportitem"><b>${q[1]}</b><p>${esc(data.answers[q[0]]||'Non renseigné')}</p></div>`).join('')}</details><div class="card"><h3>Garder ou transmettre mon bilan</h3><p class="small">Le PDF contient mes coordonnées et mes réponses. Je choisis moi-même de le partager.</p><div class="actions"><button id="download">↓ Télécharger mon PDF</button><button id="share" class="quiet">Partager le PDF</button><button id="emailSend" class="quiet">Envoyer par email</button></div><p class="small">Destinataire : contact@ombaliz.com. L’email ouvre votre messagerie ; vous devrez joindre le PDF téléchargé. Aucun envoi automatique.</p><p id="pdfStatus" role="status"></p></div><button id="reset" class="textbtn">Effacer mes réponses et recommencer</button>`}
function render(){ $('#steps').innerHTML=titles.map((t,i)=>`<button class="${i===step?'active':''}" data-step="${i}" ${i===step?'aria-current="step"':''}><b>${i+1}</b>${t}</button>`).join('');$('#stepLabel').textContent=`ÉTAPE ${step+1} / 6 · ${titles[step]}`;$('#completion').textContent=`${Math.round((step+1)/6*100)} % du parcours`;$('#progress').value=step+1;$('#content').innerHTML=step===0?welcome():step<4?`<div class="portrait">${symbols(step-1)}</div><div class="eyebrow">${groups[step-1].sub}</div><h2>${groups[step-1].title}</h2><p class="lead">${groups[step-1].intro}</p><div class="note">${groups[step-1].tip}</div><div class="note"><b>Le lien avec Johari</b><br>${johariLinks[step-1]}</div><p class="small">Je peux choisir jusqu’à 3 questions prioritaires avec l’étoile.</p>${groups[step-1].q.map(q=>question(q)).join('')}<div class="card"><h3>Mon ressenti aujourd’hui</h3><p class="small">Je réponds selon mon vécu actuel. Une échelle laissée vide reste « non renseignée ».</p>${groups[step-1].s.map(scale).join('')}</div>`:step===4?bridge():report();$('#back').disabled=step===0;$('#next').hidden=step===5;bind();}
function validate(){if(!data.email||!$('#email')?.checkValidity()&&step===0||!/^\+?[\d\s().-]{6,25}$/.test(data.phone)){if(step!==0){step=0;render()}$('#validation').innerHTML='<p class="error">Renseignez une adresse email valide et un numéro de téléphone pour commencer.</p>';$('#email').reportValidity();return false}return true}
function go(i){if(step===0&&i>0&&!validate())return;step=i;render();$('#content').focus();window.scrollTo({top:0,behavior:'smooth'})}
function bind(){document.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{data.answers[el.dataset.answer]=el.value;save()});document.querySelectorAll('[data-score]').forEach(el=>el.onclick=()=>{const id=el.dataset.score;data.scores[id]=Number(el.dataset.value);save();document.querySelectorAll(`[data-score="${id}"]`).forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',String(b===el))});$('#out-'+id).firstChild.textContent=data.scores[id]+' / 10 '});document.querySelectorAll('[data-clear]').forEach(el=>el.onclick=()=>{delete data.scores[el.dataset.clear];save();render()});document.querySelectorAll('[data-priority]').forEach(el=>el.onclick=()=>{const id=el.dataset.priority;if(data.priorities.includes(id))data.priorities=data.priorities.filter(x=>x!==id);else if(data.priorities.length<3)data.priorities.push(id);else return toast('Vous avez déjà choisi 3 priorités. Retirez une étoile pour en choisir une autre.');save();el.classList.toggle('chosen',data.priorities.includes(id));el.setAttribute('aria-pressed',data.priorities.includes(id));el.textContent=data.priorities.includes(id)?'★ Priorité':'☆ Prioriser'});document.querySelectorAll('[data-step]').forEach(el=>el.onclick=()=>go(Number(el.dataset.step)));for(const id of ['email','phone'])if($('#'+id))$('#'+id).oninput=e=>{data[id]=e.target.value.trim();save()};if($('#remember'))$('#remember').onchange=e=>{data.remember=e.target.checked;if(data.remember)save();else try{localStorage.removeItem('ombaliz-image-v1')}catch{}};if($('#download'))$('#download').onclick=()=>exportPdf('download');if($('#share'))$('#share').onclick=()=>exportPdf('share');if($('#emailSend'))$('#emailSend').onclick=()=>{window.location.href='mailto:contact@ombaliz.com?subject='+encodeURIComponent('Mon bilan – Image de soi')+'&body='+encodeURIComponent('Bonjour,\n\nJe souhaite vous transmettre mon bilan « Image de soi » complété le '+dateLabel()+'.\n\nJe joins mon PDF à ce message.\n\nBonne journée.');toast('Pensez à télécharger puis à joindre votre PDF au message.');};if($('#reset'))$('#reset').onclick=()=>modal('<h2>Effacer mon carnet ?</h2><p>Mes réponses seront supprimées de cet onglet et de la sauvegarde locale. Les PDF déjà téléchargés restent sur mon appareil.</p><button id="confirmReset">Oui, effacer</button>');if($('#confirmReset'))$('#confirmReset').onclick=reset;}
function reset(){try{localStorage.removeItem('ombaliz-image-v1')}catch{}data={date:new Date().toISOString(),answers:{},scores:{},priorities:[],email:'',phone:'',remember:false};$('#modal').close();step=0;render()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal();if($('#confirmReset'))$('#confirmReset').onclick=reset}
$('#modal .close').onclick=()=>$('#modal').close();$('#back').onclick=()=>go(step-1);$('#next').onclick=()=>go(step+1);$('#home').onclick=e=>{e.preventDefault();go(0)};
$('#qrOpen').onclick=()=>modal(`<div class="eyebrow">MON PARCOURS À PORTÉE DE MAIN</div><h2>Continuer sur mon téléphone</h2><img class="qr" src="assets/qr.png" alt="QR code pour ouvrir l’application"><p>Scannez ce code pour ouvrir l’application sur iOS ou Android.</p><p class="small">Le code contient uniquement l’adresse du site. Les réponses restent sur l’appareil où elles ont été saisies ; elles ne sont pas transférées par le code.</p><a href="https://ombaliz-image-de-soi.onrender.com">Ouvrir l’application</a><details><summary>Ajouter à mon écran d’accueil</summary><p>iPhone / iPad : dans Safari, Partager puis « Sur l’écran d’accueil ».<br>Android : dans le menu du navigateur, « Ajouter à l’écran d’accueil ».</p></details>`);
$('#resources').onclick=()=>modal(`<div class="eyebrow">POUR COMPRENDRE LE CADRE</div><h2>Ressources & confidentialité</h2><h3>Un support de réflexion</h3><p>Structure issue de « L’image de soi », Michel Laks, Ombaliz. Les ajouts sont des questions originales, et non la reproduction de questionnaires validés.</p><p>La fenêtre de Johari (Luft et Ingham, 1955) croise ce que je connais de moi et ce que les autres connaissent. Ses quatre zones sont ouverte, cachée, aveugle et inconnue. Elle complète ce carnet sans se confondre avec ses trois facettes.</p><p>Le modèle des écarts entre les représentations de soi de Higgins distingue notamment soi actuel, idéal et prescrit. Il éclaire ici la différence entre aspiration et obligation ; il n’est pas équivalent aux trois facettes de ce carnet.</p><ul><li><a href="${johariSource}" target="_blank" rel="noopener">Joseph Luft (1961), The Johari Window — modèle introduit avec Harrington Ingham en 1955</a></li><li><a href="https://www.columbia.edu/cu/psychology/higgins/papers/HIGGINS%3DPSYCH%20REVIEW%201987.pdf" target="_blank" rel="noopener">Higgins (1987), Self-discrepancy: A theory relating self and affect</a></li><li><a href="https://doi.org/10.1146/annurev-psych-032420-031047" target="_blank" rel="noopener">Neff (2023), Self-Compassion: Theory, Method, Research, and Intervention</a></li><li><a href="https://self-compassion.org/exercises/" target="_blank" rel="noopener">Exercices d’autocompassion de Kristin Neff (en anglais)</a></li></ul><p>Les propositions de dialogue bienveillant et de petit pas sont des adaptations pédagogiques. Ce carnet n’est ni un test diagnostique ni une mesure validée des états du moi.</p><h3>Mes données</h3><p>Les réponses ne sont pas envoyées à Ombaliz et ne sont pas enregistrées dans une base de données de l’application. Elles restent dans la mémoire de cet onglet, ou sur cet appareil si je choisis la sauvegarde locale. L’hébergement peut traiter les données techniques habituelles de connexion. Aucun outil de suivi publicitaire n’est intégré.</p><p>Le PDF est généré sur mon appareil. Je décide de l’envoyer et je vérifie le destinataire et la pièce jointe. Une messagerie ordinaire ne garantit pas la confidentialité d’un échange de santé ; je peux convenir d’un autre mode de transmission avec mon thérapeute.</p><p>Je peux effacer les réponses depuis mon bilan. En cas d’inconfort, je peux arrêter l’exercice et revenir à ce qui m’aide à me sentir présent(e).</p>`);
async function makePdf(){if(!window.jspdf)throw Error('Le générateur PDF est indisponible. Rechargez la page après avoir conservé vos réponses.');const doc=new window.jspdf.jsPDF();let y=45;const width=174;const clean=s=>String(s??'').replace(/[★☆]/g,'*').replace(/[’‘]/g,"'").replace(/[“”]/g,'"').replace(/[–—]/g,'-').replace(/→/g,'vers').replace(/…/g,'...');const logo=new Image();logo.src='assets/logo.png';await logo.decode();const ratio=logo.naturalHeight/logo.naturalWidth;const addHeader=()=>{doc.setFillColor(247,246,241);doc.rect(0,0,210,297,'F');doc.addImage(logo,'PNG',18,8,45,45*ratio);doc.setTextColor(24,63,71);doc.setFontSize(9);doc.text('OMBALIZ THERAPIE | MON IMAGE DE SOI',192,18,{align:'right'});doc.setDrawColor(215,223,216);doc.line(18,39,192,39)};addHeader();const page=()=>{doc.addPage();addHeader();y=47};const text=(s,size=10,bold=false)=>{doc.setFont('helvetica',bold?'bold':'normal');doc.setFontSize(size);const lines=doc.splitTextToSize(clean(s),width);for(const line of lines){if(y>273)page();doc.text(line,18,y);y+=size*.47+1.1}y+=3};const heading=s=>{if(y>246)page();y+=5;doc.setTextColor(132,57,82);text(s,15,true);doc.setTextColor(24,63,71)};text('Mon carnet de reflexion',24,true);text('Date de reponse : '+dateLabel());text('Email : '+data.email);text('Telephone : '+data.phone);text("Une photographie subjective de mon vecu. Outil de dialogue, sans diagnostic ni score global. Les echelles de ce carnet ne sont pas des tests valides.",10);heading('La fenetre de Johari, simplement');text('Luft et Ingham (1955) : quatre zones pour reflechir a ce que je connais de moi et a ce que les autres en percoivent.');for(const a of johariAreas){text(a[0]+' : '+a[1]);}text('Ces zones varient selon la relation et le contexte. Elles completent les trois regards sans leur correspondre terme a terme. Le moi ideal est une direction souhaitee, pas une zone de Johari. Je choisis ce que je partage, a mon rythme.');heading('Mes priorites');if(!data.priorities.length)text('Aucune priorite selectionnee.');for(const id of data.priorities){const q=allQ().find(q=>q[0]===id);text('* '+q[1],11,true);text(data.answers[id]||'A explorer en seance.')}for(const g of groups){heading(g.title);text(g.intro);text('Le lien avec Johari : '+johariLinks[groups.indexOf(g)]);for(const q of g.q){text((data.priorities.includes(q[0])?'* ':'')+q[1],11,true);text(data.answers[q[0]]||'Non renseigne');}text('Mon ressenti aujourd’hui',12,true);for(const s of g.s)text(s[1]+'\n'+(data.scores[s[0]]===undefined?'Non renseigne':data.scores[s[0]]+' / 10')+' | 0 : '+s[2]+' ; 10 : '+s[3]);}heading('Mes passerelles');for(const q of bridgeQ){text((data.priorities.includes(q[0])?'* ':'')+q[1],11,true);text(data.answers[q[0]]||'Non renseigne')}for(const s of bridgeS)text(s[1]+'\n'+(data.scores[s[0]]===undefined?'Non renseigne':data.scores[s[0]]+' / 10')+' | 0 : '+s[2]+' ; 10 : '+s[3]);heading('Cadre et ressources');text("Structure : L'image de soi, Michel Laks, Ombaliz. Moi reel, moi presente, moi ideal. Ces facettes sont distinctes des etats Parent, Adulte et Enfant de l'analyse transactionnelle.");text('Luft, J. (1961). The Johari Window: A Graphic Model of Awareness in Interpersonal Relations. Human Relations Training News, 5(1), 6-7. Modele introduit avec H. Ingham en 1955. Ressource : ombuds.columbia.edu (lien complet dans les ressources de l’application).');text('Higgins, E. T. (1987). Self-discrepancy: A theory relating self and affect. Psychological Review, 94(3), 319-340. doi:10.1037/0033-295X.94.3.319');text('Neff, K. D. (2023). Self-Compassion: Theory, Method, Research, and Intervention. Annual Review of Psychology, 74, 193-217. doi:10.1146/annurev-psych-032420-031047');text('Questions et exercices originaux : adaptations pedagogiques, sans validation psychometrique propre. Aucune interpretation automatique des scores.');text('Destinataire souhaite : contact@ombaliz.com. Le partage reste au choix du patient. Aucun envoi automatique.');const n=doc.getNumberOfPages();for(let i=1;i<=n;i++){doc.setPage(i);doc.setFontSize(8);doc.setTextColor(93,112,113);doc.text('CONFIDENTIEL - Document personnel | Ombaliz Therapie',18,287);doc.text(i+' / '+n,192,287,{align:'right'})}return doc;}
async function exportPdf(mode){const status=$('#pdfStatus');status.textContent='Préparation de mon PDF…';try{const doc=await makePdf();const filename='Ombaliz_Image_de_soi_'+data.date.slice(0,10)+'.pdf';if(mode==='share'){const file=new File([doc.output('blob')],filename,{type:'application/pdf'});if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:'Mon bilan — Image de soi'});status.textContent='Partage ouvert.';return}doc.save(filename);status.textContent='Le partage de fichier n’est pas disponible ici. PDF téléchargé : joignez-le à votre email.';}else{doc.save(filename);status.textContent='PDF préparé. Retrouvez-le dans les téléchargements de votre navigateur.'}}catch(e){status.textContent=e.name==='AbortError'?'Partage annulé.':'Le PDF n’a pas pu être créé : '+e.message;}}
render();
